    private static MCQQuestion q(int id, String skill, String prompt, int d,
                                 String[] options, int correct, String hint, String explanation) {
        return new MCQQuestion(id, skill, prompt, d, List.of(options), correct, explanation, hint);
    }

    public static List<Question> questions() {
        List<Question> b = new ArrayList<>();
        // The original 100-question bank is preserved and normalized for the new learner model.
        B(b);
        return List.copyOf(b);
    }

